$ErrorActionPreference = 'Stop'
Set-StrictMode -Version Latest
$Project = 'C:\shabashka_app'
$BackupRoot = 'C:\shabashka_backups'
$Stamp = Get-Date -Format 'yyyyMMdd_HHmmss'
$Backup = Join-Path $BackupRoot ('package6_' + $Stamp)
New-Item -ItemType Directory -Force -Path $Backup | Out-Null
$Utf8NoBom = New-Object System.Text.UTF8Encoding($false, $true)
function Decode-B64([string]$Value) { return [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($Value)) }
function Get-Sha256([string]$Path) { return (Get-FileHash -Algorithm SHA256 -LiteralPath $Path).Hash.ToLowerInvariant() }
function Replace-Exactly([string]$Text, [string]$Old, [string]$New, [string]$Label) {
  $Count = ([regex]::Matches($Text, [regex]::Escape($Old))).Count
  if ($Count -ne 1) { throw ($Label + ': expected 1 match, got ' + $Count) }
  return $Text.Replace($Old, $New)
}
$Plans = @()
